/** Build the SVG/HTML node for an approved chart key at the given language. */
export function buildChartNode(key, lang) {
  LANG = lang === "ko" || lang === "ja" || lang === "en" ? lang : "ja";
  const b = BUILD[key];
  if (!b) return null;
  try {
    return b.render();
  } catch (e) {
    return null;
  }
}

export function hasChart(key) {
  return !!BUILD[key];
}
